PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS source_registry(source_id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,source_kind TEXT NOT NULL,origin_url TEXT,publisher_owner TEXT,version TEXT NOT NULL,retrieved_at TEXT NOT NULL,checksum TEXT,license_name TEXT NOT NULL,license_url TEXT,usage_scope TEXT NOT NULL,attribution_text TEXT NOT NULL,share_alike_required INTEGER NOT NULL,redistribution_allowed INTEGER NOT NULL,commercial_use_status TEXT NOT NULL,raw_retention_policy TEXT NOT NULL,notes TEXT,license_status TEXT NOT NULL DEFAULT 'LICENSE_UNKNOWN',display_allowed INTEGER NOT NULL DEFAULT 0,generation_allowed INTEGER NOT NULL DEFAULT 0,internal_use_allowed INTEGER NOT NULL DEFAULT 0,attribution_required INTEGER NOT NULL DEFAULT 0,license_verified_at TEXT,license_evidence_url TEXT);
CREATE TABLE IF NOT EXISTS corpus_schema_migrations(version INTEGER PRIMARY KEY,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_runs(import_run_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES source_registry(source_id),source_version TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,importer_version TEXT NOT NULL,raw_checksum TEXT,rows_read INTEGER NOT NULL DEFAULT 0,rows_accepted INTEGER NOT NULL DEFAULT 0,rows_rejected INTEGER NOT NULL DEFAULT 0,rows_deduped INTEGER NOT NULL DEFAULT 0,warnings TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL,parser_version TEXT NOT NULL DEFAULT 'unknown',normalizer_version TEXT NOT NULL DEFAULT 'unknown',manifest_checksum TEXT,entity_counts_json TEXT NOT NULL DEFAULT '{}',source_drift_status TEXT NOT NULL DEFAULT 'MATCHED');
CREATE TABLE IF NOT EXISTS raw_assets(raw_asset_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES source_registry(source_id),cache_path TEXT NOT NULL,file_type TEXT NOT NULL,checksum TEXT NOT NULL,record_range TEXT,privacy_scope TEXT NOT NULL,committed_to_git INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS lexemes(lexeme_id TEXT PRIMARY KEY,lemma TEXT NOT NULL,normalized_lemma TEXT NOT NULL,pos TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_record_id TEXT NOT NULL,UNIQUE(normalized_lemma,pos,source_id,source_record_id));
CREATE TABLE IF NOT EXISTS senses(sense_id TEXT PRIMARY KEY,lexeme_id TEXT NOT NULL REFERENCES lexemes(lexeme_id),synset_id TEXT NOT NULL,glosses_json TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_record_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lexical_relations(relation_id TEXT PRIMARY KEY,from_record_id TEXT NOT NULL,relation_type TEXT NOT NULL,to_record_id TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS morphology(morphology_id TEXT PRIMARY KEY,lemma TEXT NOT NULL,normalized_lemma TEXT NOT NULL,form TEXT NOT NULL,normalized_form TEXT NOT NULL,features TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_record_id TEXT NOT NULL,UNIQUE(normalized_lemma,normalized_form,features,source_id));
CREATE TABLE IF NOT EXISTS frequencies(frequency_id TEXT PRIMARY KEY,lemma TEXT NOT NULL,metric TEXT NOT NULL,value REAL NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_record_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sentences(sentence_id TEXT PRIMARY KEY,language TEXT NOT NULL,text TEXT NOT NULL,normalized_text TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_sentence_id TEXT NOT NULL,contributor TEXT,record_license TEXT);
CREATE TABLE IF NOT EXISTS translation_pairs(pair_id TEXT PRIMARY KEY,from_sentence_id TEXT NOT NULL REFERENCES sentences(sentence_id),to_sentence_id TEXT NOT NULL REFERENCES sentences(sentence_id),source_id TEXT NOT NULL,source_version TEXT NOT NULL,source_record_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS examples(example_id TEXT PRIMARY KEY,synset_id TEXT NOT NULL,text TEXT NOT NULL,normalized_text TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_registry(source_id),source_version TEXT NOT NULL,source_record_id TEXT NOT NULL,UNIQUE(synset_id,normalized_text,source_id));
CREATE TABLE IF NOT EXISTS sentence_clusters(cluster_id TEXT PRIMARY KEY,language TEXT NOT NULL,normalized_text TEXT NOT NULL,UNIQUE(language,normalized_text));
CREATE TABLE IF NOT EXISTS sentence_cluster_members(cluster_id TEXT NOT NULL REFERENCES sentence_clusters(cluster_id),sentence_id TEXT NOT NULL UNIQUE REFERENCES sentences(sentence_id),source_id TEXT NOT NULL REFERENCES source_registry(source_id),source_record_id TEXT NOT NULL,PRIMARY KEY(cluster_id,sentence_id));
CREATE TABLE IF NOT EXISTS sentence_provenance(sentence_id TEXT PRIMARY KEY REFERENCES sentences(sentence_id),source_id TEXT NOT NULL REFERENCES source_registry(source_id),source_version TEXT NOT NULL,source_sentence_id TEXT NOT NULL,contributor TEXT,record_license TEXT,license_status TEXT NOT NULL,attribution_text TEXT,attribution_required INTEGER NOT NULL DEFAULT 0,provenance_complete INTEGER NOT NULL DEFAULT 0,source_integrity_valid INTEGER NOT NULL DEFAULT 0,record_quality_valid INTEGER NOT NULL DEFAULT 0,usage_eligibility TEXT NOT NULL,quarantine_reason TEXT,import_run_id TEXT REFERENCES import_runs(import_run_id),raw_asset_id TEXT REFERENCES raw_assets(raw_asset_id),source_checksum TEXT NOT NULL,acquired_at TEXT NOT NULL,UNIQUE(source_id,source_version,source_sentence_id));
CREATE TABLE IF NOT EXISTS data_quality_runs(quality_run_id TEXT PRIMARY KEY,started_at TEXT NOT NULL,completed_at TEXT,validator_version TEXT NOT NULL,status TEXT NOT NULL,metrics_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS data_quality_issues(issue_id TEXT PRIMARY KEY,quality_run_id TEXT NOT NULL REFERENCES data_quality_runs(quality_run_id),severity TEXT NOT NULL,check_name TEXT NOT NULL,source_id TEXT,record_id TEXT,message TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS retrieval_index_state(index_name TEXT PRIMARY KEY,index_version TEXT NOT NULL,source_fingerprint TEXT NOT NULL,built_at TEXT NOT NULL,row_count INTEGER NOT NULL,status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_lexeme_lemma ON lexemes(normalized_lemma);
CREATE INDEX IF NOT EXISTS idx_sense_synset ON senses(synset_id);
CREATE INDEX IF NOT EXISTS idx_morph_form ON morphology(normalized_form);
CREATE INDEX IF NOT EXISTS idx_sentence_language_text ON sentences(language,normalized_text);
CREATE INDEX IF NOT EXISTS idx_source_lexeme ON lexemes(source_id);
CREATE INDEX IF NOT EXISTS idx_source_sentence ON sentences(source_id);
CREATE INDEX IF NOT EXISTS idx_examples_synset ON examples(synset_id);
CREATE INDEX IF NOT EXISTS idx_cluster_text ON sentence_clusters(language,normalized_text);
CREATE INDEX IF NOT EXISTS idx_sentence_provenance_eligibility ON sentence_provenance(usage_eligibility,license_status);
CREATE INDEX IF NOT EXISTS idx_pair_from_to ON translation_pairs(from_sentence_id,to_sentence_id);
CREATE INDEX IF NOT EXISTS idx_morph_lemma ON morphology(normalized_lemma);
CREATE VIRTUAL TABLE IF NOT EXISTS sentences_fts USING fts5(sentence_id UNINDEXED,normalized_text,language UNINDEXED);
